dist/styles.css.beforeText:
:root {
  color-scheme: light;
  --navy: #203864;
  --navy-deep: #142743;
  --blue: #4472c4;
  --blue-strong: #2f5597;
  --blue-soft: #d9e7f7;
  --blue-pale: #edf4fb;
  --grid: #aebbd0;
  --ink: #172033;
  --muted: #627087;
  --paper: #ffffff;
  --canvas: #e8eef6;
  --shadow: 0 12px 30px rgba(25, 52, 91, 0.11);
  font-family: "Microsoft YaHei", "PingFang SC", "Noto Sans CJK SC", system-ui, sans-serif;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  min-width: 320px;
  background: var(--canvas);
  color: var(--ink);
  font-size: 16px;
}

button, input, textarea { font: inherit; }

.site-header {
  min-height: 78px;
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px clamp(16px, 3vw, 46px);
  color: #fff;
  background: linear-gradient(120deg, var(--navy-deep), var(--navy) 52%, var(--blue-strong));
  border-bottom: 4px solid #88aee4;
}

.brand-mark {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border: 1px solid rgba(255,255,255,.58);
  background: rgba(255,255,255,.12);
  font-weight: 800;
  letter-spacing: .04em;
}

.site-header h1 {
  margin: 0;
  font-size: clamp(1.18rem, 2vw, 1.55rem);
  line-height: 1.25;
}

.site-header p {
  margin: 4px 0 0;
  color: #d9e8ff;
  font-size: .875rem;
}

.brand-copy { min-width: 0; }

.header-nav-link {
  margin-left: auto;
  padding: 9px 14px;
  border: 1px solid rgba(255,255,255,.62);
  color: #fff;
  text-decoration: none;
  font-size: .9rem;
  font-weight: 700;
  white-space: nowrap;
  background: rgba(255,255,255,.1);
}

.header-nav-link:hover { background: rgba(255,255,255,.2); }
.header-actions { display:flex; flex-wrap:wrap; gap:8px; margin-left:auto; }
.header-actions .header-nav-link { margin-left:0; }

main { padding: 18px clamp(10px, 2vw, 28px) 42px; }

.workspace {
  width: min(1900px, 100%);
  margin: 0 auto;
  background: var(--paper);
  border: 1px solid #c9d4e4;
  box-shadow: var(--shadow);
}

.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 14px 16px;
  background: #f8fbff;
  border-bottom: 1px solid #cad6e6;
}

.search-box {
  width: min(620px, 100%);
  min-height: 44px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 8px 0 13px;
  background: #fff;
  border: 2px solid #9db6d7;
}

.search-box:focus-within {
  border-color: var(--blue);
  box-shadow: 0 0 0 3px rgba(68,114,196,.14);
}

.search-icon { color: var(--blue-strong); font-size: 1.25rem; }

.search-box input {
  width: 100%;
  min-width: 0;
  border: 0;
  outline: 0;
  color: var(--ink);
  background: transparent;
}

.search-box button,
.back-top {
  border: 1px solid #9fb2cc;
  background: #fff;
  color: var(--blue-strong);
  cursor: pointer;
}

.search-box button { padding: 6px 10px; white-space: nowrap; }
.back-top { padding: 8px 12px; }
.search-box button:hover, .back-top:hover { background: var(--blue-pale); }

.result-summary {
  color: var(--muted);
  font-size: .875rem;
  white-space: nowrap;
}

.sheet-tabs {
  display: flex;
  gap: 2px;
  overflow-x: auto;
  padding: 9px 10px 0;
  background: #dbe5f1;
  border-bottom: 1px solid #9fb0c7;
  scrollbar-width: thin;
}

.sheet-tab {
  flex: 0 0 auto;
  min-height: 40px;
  padding: 8px 13px;
  border: 1px solid #9fb0c7;
  border-bottom: 0;
  background: #edf2f8;
  color: #30445f;
  cursor: pointer;
  font-size: .9rem;
}

.sheet-tab:hover { background: #fff; }

.sheet-tab[aria-selected="true"] {
  position: relative;
  z-index: 1;
  background: #fff;
  color: var(--blue-strong);
  font-weight: 700;
}

.sheet-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 12px;
  padding: 18px 16px 12px;
}

.sheet-kicker {
  display: block;
  margin-bottom: 2px;
  color: var(--muted);
  font-size: .76rem;
  letter-spacing: .08em;
}

.sheet-heading h2 { margin: 0; font-size: 1.35rem; color: var(--navy); }

.edit-hint {
  display: inline-block;
  margin-top: 5px;
  color: var(--muted);
  font-size: .8rem;
}

.table-area { padding: 0 12px 18px; }

.split-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(960px, 1fr));
  gap: 18px;
  overflow-x: auto;
  padding-bottom: 4px;
}

.table-scroll { overflow-x: auto; }

.excel-table {
  color: #111;
  width: 100%;
  min-width: 780px;
  border-collapse: collapse;
  table-layout: fixed;
  font-size: .84rem;
  line-height: 1.55;
}

.excel-table col.type { width: 10%; }
.excel-table col.name { width: 18%; }
.excel-table col.effect { width: 60%; }
.excel-table col.rating { width: 7%; }
.excel-table col.action { width: 5%; }
.excel-table.all-skills col.effect { width: 70%; }

/* Ordinary list follows the workbook; the labeling table keeps its own layout. */
.skill-list-table { min-width: 960px; font-size: .875rem; }
.skill-list-table col.type { width: 10%; }
.skill-list-table col.name { width: 16%; }
.skill-list-table col.sc { width: 6%; }
.skill-list-table col.effect { width: 34%; }
.skill-list-table col.sources { width: 24%; }
.skill-list-table col.rating { width: 5%; }
.skill-list-table col.action { width: 5%; }
.skill-list-table.all-skills col.name { width: 20%; }
.skill-list-table.all-skills col.effect { width: 40%; }
.skill-list-table .source-list > div + div { margin-top: 4px; }

.excel-table th,
.excel-table td {
  border: 1px solid var(--grid);
  padding: 6px 7px;
  vertical-align: top;
  background: #fff;
  overflow-wrap: anywhere;
}

.excel-table tbody tr,
.excel-table tbody td {
  height: auto;
}

.cell-content {
  width: 100%;
  height: auto;
  overflow: visible;
  padding: 2px 3px;
}

.cell-content.cell-center {
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
}

.excel-table thead .book-title th {
  padding: 10px;
  color: #111;
  background: #fff;
  font-size: .95rem;
  letter-spacing: .02em;
  text-align: center;
}

.excel-table thead .column-title th {
  position: sticky;
  top: 0;
  z-index: 2;
  color: #111;
  background: #fff;
  font-weight: 700;
  text-align: center;
}

.skill-list-table thead .book-title th { color: #fff; background: var(--navy); }
.skill-list-table thead .column-title th { color: #fff; background: var(--blue); }

.judgment-cell .judgment-ready { color: #111; }
.judgment-cell .judgment-partial { color: #175cd3; }
.judgment-cell .judgment-unknown { color: #b42318; }
.judgment-label { font-weight: 600; }
.excel-table .judgment-cell { padding-inline: 4px; }
.skill-tag-note { margin: 0; }
.skill-tags-cell .skill-stat-metadata { margin-top: 0; padding-top: 0; border-top: 0; }
.excel-table mark { color: inherit; background: #fff; text-decoration: underline; font-weight: 700; }

.editable-cell { cursor: text; }
.editable-cell:hover { box-shadow: inset 0 0 0 2px rgba(68, 114, 196, .35); }
.editable-cell.is-editing { padding: 4px; background: #fff !important; box-shadow: inset 0 0 0 2px var(--blue); }

.cell-editor {
  width: 100%;
  height: 72px;
  min-width: 0;
  margin: 0;
  padding: 7px 8px;
  border: 1px solid #6f8fbc;
  outline: 0;
  background: #fff;
  color: var(--ink);
  font: inherit;
  line-height: 1.45;
  resize: none;
}

input.cell-editor { height: 40px; text-align: center; }

.excel-table .separator-row,
.excel-table .separator-row td {
  height: 24px;
  min-height: 24px;
  padding: 0;
  background: #fff;
  border-left-color: transparent;
  border-right-color: transparent;
}

.excel-table .separator-row td {
  border-top: 2px solid #8fa7c6;
  border-bottom: 2px solid #8fa7c6;
}

.type-cell {
  width: 11%;
  background: #fff;
  color: #111;
  font-weight: 700;
  text-align: center;
}

.skill-name { font-weight: 700; color: inherit; }
.skill-name a { color: inherit; text-decoration-thickness: 1px; text-underline-offset: 3px; }
.skill-name a:hover { color: inherit; }
.rating-cell { text-align: center; font-weight: 800; color: inherit; white-space: nowrap; }

.action-cell { text-align: center; }

.add-skill-button {
  width: 32px;
  height: 32px;
  display: inline-grid;
  place-items: center;
  padding: 0;
  border: 1.5px solid #35445b;
  border-radius: 50%;
  background: #fff;
  color: #27364c;
  cursor: pointer;
  box-shadow: 0 1px 2px rgba(25,52,91,.1);
  transition: color .15s, border-color .15s, background .15s, transform .15s;
}

.add-skill-button span {
  display: block;
  font-size: 1.35rem;
  font-weight: 500;
  line-height: 1;
  transform: translateY(-1px);
}

.add-skill-button:hover { border-color: var(--blue); background: var(--blue-pale); transform: translateY(-1px); }
.add-skill-button.is-added { border-color: #3f8c5b; background: #edf8f0; color: #287043; }
.add-skill-button.is-added span { font-size: 1.05rem; font-weight: 700; transform: none; }

.sc-calculator[hidden] { display: none !important; }

.calculator-launcher {
  position: fixed;
  right: 18px;
  bottom: 18px;
  z-index: 30;
  min-width: 58px;
  min-height: 46px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 6px;
  border: 1px solid #b7c7dc;
  border-radius: 14px;
  background: var(--navy);
  color: #fff;
  box-shadow: 0 10px 28px rgba(20,39,67,.26);
  cursor: pointer;
}

.calculator-launcher:hover { background: var(--blue-strong); }
.calculator-launcher strong { padding: 5px 8px; border-radius: 8px; background: #fff; color: var(--navy); white-space: nowrap; }

.sc-calculator {
  position: fixed;
  right: 18px;
  bottom: 80px;
  z-index: 31;
  width: min(400px, calc(100vw - 24px));
  max-height: min(680px, calc(100vh - 110px));
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid #aabbd2;
  border-radius: 16px;
  background: #fff;
  box-shadow: 0 18px 50px rgba(20,39,67,.28);
}

.calculator-header {
  min-height: 48px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) 34px;
  align-items: center;
  gap: 7px;
  padding: 7px 10px;
  background: var(--navy);
  color: #fff;
}

.calculator-header > strong { min-width: 0; overflow: hidden; font-size: .92rem; text-align: center; text-overflow: ellipsis; white-space: nowrap; }
.calculator-sort-actions { display: flex; align-items: center; gap: 2px; }

.calculator-sort {
  width: auto;
  min-width: 42px;
  height: 34px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: #fff;
  cursor: pointer;
}

.calculator-sort:hover { background: rgba(255,255,255,.13); }
.calculator-sort.is-active { background: rgba(255,255,255,.18); }
.calculator-sort span { font-size: .75rem; font-weight: 700; line-height: 1; white-space: nowrap; }
.calculator-close { width: 34px; height: 34px; border: 0; border-radius: 50%; background: rgba(255,255,255,.13); color: #fff; font-size: 1.35rem; cursor: pointer; }

.calculator-plan-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
  padding: 8px 10px;
  background: #edf4fb;
  border-bottom: 1px solid #cad6e6;
}

.calculator-plan-actions button {
  min-height: 36px;
  border: 1px solid #9fb3cf;
  background: #fff;
  color: var(--navy);
  font-weight: 700;
  cursor: pointer;
}

.calculator-plan-actions button:hover { background: #dcecff; }
.calculator-plan-actions span { display: inline-grid; place-items: center; min-width: 22px; height: 22px; margin-left: 4px; border-radius: 11px; background: var(--navy); color: #fff; font-size: .74rem; }

.break-buttons {
  display: grid;
  grid-template-columns: repeat(3, 68px) minmax(62px, 1fr) 76px;
  gap: 5px;
  padding: 12px 14px 8px;
}

.break-buttons button {
  position: relative;
  min-height: 36px;
  padding: 4px 32px 4px 6px;
  border: 1px solid #aeb9c8;
  border-radius: 20px;
  background: #d1d4d7;
  color: #445063;
  font-weight: 700;
  font-size: .9rem;
  cursor: pointer;
  transition: background .16s, border-color .16s;
}

.break-buttons button::before {
  content: '';
  position: absolute;
  top: 50%;
  right: 4px;
  width: 24px;
  height: 24px;
  border: 1px solid #727b86;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 1px 3px rgba(0,0,0,.3);
  transform: translateY(-50%);
  transition: right .16s;
}

.break-buttons button.is-active {
  padding-right: 6px;
  padding-left: 32px;
  border-color: var(--blue-strong);
  background: var(--blue);
  color: #fff;
}

.break-buttons button.is-active::before { right: calc(100% - 28px); border-color: #fff; }

.break-buttons .calculator-details,
.break-buttons .calculator-mode-button {
  padding: 5px 10px;
  border-radius: 9px;
  background: #fff;
  color: var(--blue-strong);
}

.break-buttons .calculator-details::before,
.break-buttons .calculator-mode-button::before { display: none; }
.break-buttons .calculator-details:hover,
.break-buttons .calculator-mode-button:hover { background: var(--blue-pale); }
.break-buttons .calculator-details.is-active,
.break-buttons .calculator-mode-button.is-active { padding: 5px 10px; background: var(--navy); color: #fff; }

.calculator-skills { min-height: 86px; overflow-y: auto; border-top: 1px solid #dce4ef; }
.calculator-empty { padding: 30px 16px; color: var(--muted); text-align: center; }

.calculator-skill {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 60px 88px 30px;
  align-items: center;
  column-gap: 10px;
  row-gap: 8px;
  padding: 10px 12px;
  border-bottom: 1px solid #e2e8f1;
}

.calculator-skill-name { min-width: 0; padding: 0; border: 0; color: inherit; background: transparent; font: inherit; font-weight: 700; text-align: left; overflow-wrap: anywhere; cursor: pointer; }
.calculator-skill-name:hover { color: var(--blue-strong); }
.calculator-skill-rating { width: 100%; min-height: 28px; padding: 3px 5px; border: 1px solid #b7c6da; border-radius: 5px; color: #7147a6; background: #f9f7ff; font: inherit; font-size: .74rem; font-weight: 700; text-align: center; cursor: pointer; }
.calculator-skill-rating { text-transform: uppercase; cursor: text; }
.calculator-skill-rating:hover, .calculator-skill-rating:focus { color: #7147a6; background: #fff; border-color: #7147a6; outline: 2px solid rgba(113,71,166,.18); }
.calculator-skill-rating.is-empty { color: #63738a; background: #fff; }
.calculator-skill-sc { text-align: right; white-space: nowrap; }
.calculator-skill-sc strong, .calculator-skill-sc del { display: block; }
.calculator-skill-sc del { margin-top: 1px; color: var(--muted); font-size: .7rem; }
.calculator-skill.is-free .calculator-skill-sc strong { color: #247042; }
.calculator-skill-sc small { display: block; margin-top: 2px; color: #247042; font-size: .68rem; }
.calculator-skill > [data-remove-skill] { width: 28px; height: 28px; padding: 0; border: 1px solid #bdc8d7; border-radius: 7px; background: #fff; color: #7b2e2e; cursor: pointer; }
.calculator-skill > [data-remove-skill]:hover { background: #fff0f0; }
.calculator-skill-effect { grid-column: 1 / -1; margin: 0; padding: 9px 10px; color: #536177; background: #f1f6fc; border-left: 3px solid #6f9bd2; font-size: .8rem; line-height: 1.55; }
.skill-effect-notes { margin-top: 7px; padding-top: 7px; border-top: 1px solid #dce5ef; color: inherit; font-size: .92em; line-height: 1.65; }
.skill-effect-notes > span { display: inline-block; margin-right: 7px; color: inherit; font-size: .88em; font-weight: 600; }

.bonus-summary { padding: 7px 12px 11px; }
.scenario-total{display:flex;justify-content:space-between;gap:12px;padding:11px 3px;border-bottom:2px solid #cfdbe8;font-weight:700;color:#203b60}
.scenario-total strong{color:var(--blue-strong);white-space:nowrap}
.bonus-row { width: 100%; display: flex; align-items: center; justify-content: space-between; gap: 14px; min-height: 40px; padding: 7px 3px; border: 0; border-bottom: 1px solid #e2e8f1; background: transparent; font: inherit; text-align: left; cursor: pointer; }
.bonus-row:hover, .bonus-row.is-expanded { background: var(--blue-pale); }
.bonus-row span { color: #33445c; }
.bonus-row strong { color: var(--blue-strong); white-space: nowrap; }
.bonus-sources { margin: 0 -2px 5px; border: 1px solid #cfdbea; border-top: 0; background: #f8fbff; }
.bonus-sources article { padding: 10px 11px; }
.bonus-sources article + article { border-top: 1px dashed #c9d5e5; }
.bonus-sources article > strong { display: block; margin-bottom: 4px; color: var(--navy); font-size: .88rem; }
.bonus-sources article p { margin: 0; color: #536177; font-size: .78rem; line-height: 1.55; }
.bonus-summary .bonus-note { margin: 10px 3px 1px; color: var(--muted); font-size: .75rem; line-height: 1.45; }

.calculator-total {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 13px 15px;
  border-top: 2px solid #a7b9d1;
  background: #f4f8fd;
}

.calculator-total .calculator-clear { min-height: 32px; padding: 5px 14px; border: 1px solid #b9c7d9; background: #fff; color: #8a3440; font-weight: 700; cursor: pointer; }
.calculator-total .calculator-clear:hover { background: #fff0f2; border-color: #c98992; }
.calculator-total .calculator-restore { min-height: 32px; padding: 5px 14px; border: 1px solid #b9c7d9; background: #fff; color: var(--navy); font-weight: 700; cursor: pointer; }
.calculator-total .calculator-restore:hover { background: #eaf3ff; border-color: #819fc6; }
.calculator-total .calculator-restore:disabled { opacity: .45; cursor: not-allowed; }
.calculator-total > span { margin-left: auto; }
.calculator-character-select { min-width: 0; max-width: 210px; height: 34px; padding: 4px 28px 4px 9px; border: 1px solid rgba(255,255,255,.45); border-radius: 4px; background: #fff; color: var(--navy); font: inherit; font-weight: 700; }

.calculator-total strong { color: var(--navy); font-size: 1.25rem; }

.loadout-dialog {
  width: min(520px, calc(100vw - 24px));
  max-height: min(720px, calc(100dvh - 32px));
  padding: 0;
  overflow: hidden;
  border: 1px solid #9fb2cb;
  border-radius: 14px;
  background: #fff;
  color: var(--ink);
  box-shadow: 0 22px 65px rgba(20,39,67,.35);
}

.loadout-dialog::backdrop { background: rgba(13,27,48,.48); }
.loadout-dialog form { margin: 0; }
.loadout-dialog-header { min-height: 52px; display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 9px 12px 9px 16px; background: var(--navy); color: #fff; }
.loadout-dialog-header strong { font-size: 1rem; }
.loadout-dialog-header button { width: 34px; height: 34px; padding: 0; border: 0; border-radius: 50%; background: rgba(255,255,255,.14); color: #fff; font-size: 1.25rem; cursor: pointer; }
.loadout-form { display: grid; gap: 14px; padding: 18px; }
.loadout-form label { display: grid; gap: 7px; color: #31445f; font-weight: 700; }
.loadout-form input, .loadout-form textarea { width: 100%; padding: 10px 11px; border: 1px solid #aebdd1; background: #fff; color: var(--ink); resize: vertical; font-weight: 400; }
.loadout-form input:focus, .loadout-form textarea:focus { outline: 2px solid #7aa2d7; outline-offset: 1px; }
.loadout-form p { margin: -3px 0 0; color: var(--muted); font-size: .78rem; }
.loadout-dialog-actions { display: flex; justify-content: flex-end; gap: 8px; padding: 11px 16px; border-top: 1px solid #d1dbe8; background: #f5f8fc; }
.loadout-dialog-actions button { min-height: 36px; padding: 6px 13px; border: 1px solid #a4b5cb; background: #fff; color: #314d73; font-weight: 700; cursor: pointer; }
.loadout-dialog-actions button.primary { border-color: var(--blue-strong); background: var(--blue); color: #fff; }
.saved-loadouts-dialog { overflow: hidden; }
.saved-loadouts-list { max-height: min(600px, calc(100dvh - 100px)); overflow-y: auto; padding: 12px; background: #edf3fa; }
.saved-loadout-empty { padding: 38px 16px; color: var(--muted); text-align: center; }
.saved-loadout-card { padding: 13px; border: 1px solid #b8c7d9; background: #fff; }
.saved-loadout-card + .saved-loadout-card { margin-top: 10px; }
.saved-loadout-card.is-current { border-color: var(--blue); box-shadow: inset 4px 0 0 var(--blue); }
.saved-loadout-card h3 { margin: 0; color: var(--navy); font-size: .98rem; }
.saved-loadout-card p { margin: 7px 0 0; color: #54647a; font-size: .82rem; line-height: 1.55; white-space: pre-wrap; }
.saved-loadout-meta { display: flex; flex-wrap: wrap; gap: 8px 14px; margin-top: 8px; color: var(--muted); font-size: .74rem; }
.saved-loadout-actions { display: flex; flex-wrap: wrap; gap: 7px; margin-top: 11px; }
.saved-loadout-actions button { min-height: 34px; padding: 5px 11px; border: 1px solid #a8b8cd; background: #fff; color: #315b91; font-weight: 700; cursor: pointer; }
.saved-loadout-actions button.primary { border-color: var(--blue); background: var(--blue); color: #fff; }
.saved-loadout-actions button.danger { margin-left: auto; color: #91373f; }

mark {
  padding: 0 .08em;
  color: inherit;
  background: #ffe79a;
}

.empty-state {
  margin: 0 16px 24px;
  padding: 32px 18px;
  display: grid;
  gap: 6px;
  place-items: center;
  color: var(--muted);
  border: 1px dashed #9eb0c9;
  background: #f8fbff;
  text-align: center;
}

.empty-state strong { color: var(--navy); }

@media (max-width: 760px) {
  body { font-size: 15px; }
  main { padding: 10px 0 28px; }
  .workspace { border-left: 0; border-right: 0; }
  .toolbar { align-items: stretch; flex-direction: column; }
  .result-summary { white-space: normal; }
  .sheet-heading { padding-top: 14px; }
  .table-area { padding-inline: 8px; }
  .split-grid { display: block; overflow: visible; }
  .split-grid .table-scroll + .table-scroll { margin-top: 16px; }
  .excel-table { min-width: 760px; font-size: .82rem; }
  .skill-list-table { min-width: 960px; font-size: .875rem; }
  .site-header { min-height: 70px; }
  .brand-mark { width: 42px; height: 42px; }
  .sc-calculator { right: 10px; bottom: 72px; }
  .calculator-launcher { right: 10px; bottom: 10px; }
}

@media (max-width: 420px) {
  .break-buttons { grid-template-columns: repeat(3, 52px) minmax(60px, 1fr) 64px; gap: 4px; padding-inline: 8px; }
  .break-buttons button { min-height: 34px; padding-right: 26px; padding-left: 4px; font-size: .8rem; }
  .break-buttons button::before { right: 3px; width: 21px; height: 21px; }
  .break-buttons button.is-active { padding-right: 4px; padding-left: 26px; }
  .break-buttons button.is-active::before { right: calc(100% - 24px); }
  .break-buttons .calculator-details,
  .break-buttons .calculator-mode-button { padding-inline: 5px; }
}

@media print {
  body { background: #fff; }
  .site-header, .toolbar, .sheet-tabs, .back-top, .sc-calculator, .calculator-launcher, .loadout-dialog { display: none; }
  main, .table-area { padding: 0; }
  .workspace { border: 0; box-shadow: none; }
  .split-grid { display: block; }
  .table-scroll { overflow: visible; margin-bottom: 16px; }
  .excel-table { min-width: 0; font-size: 9pt; }
  .excel-table tbody tr,
  .excel-table tbody td,
  .cell-content { height: auto; }
  .cell-content { overflow: visible; }
}

